const puppeteer = require('puppeteer');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage']
  });

  const page = await browser.newPage();

  // Set viewport to A1 portrait dimensions (at 72dpi for web)
  // A1 = 2384 x 3370 pixels at 72dpi
  await page.setViewport({
    width: 794,  // A4 width at 72dpi for testing
    height: 1123, // A4 height at 72dpi for testing
    deviceScaleFactor: 2
  });

  const filePath = path.resolve(__dirname, 'COVID-19-infographic.html');
  await page.goto(`file://${filePath}`, { waitUntil: 'networkidle0' });

  // Wait for fonts and rendering
  await page.waitForTimeout(2000);

  // Get the canvas/SVG content
  const content = await page.evaluate(() => {
    const container = document.getElementById('container');
    return container.innerHTML;
  });

  console.log('Infographic rendered successfully');
  console.log('Content length:', content.length);

  // Take screenshot
  await page.screenshot({
    path: '/app/output/final_poster.png',
    fullPage: true
  });

  console.log('Poster saved to /app/output/final_poster.png');

  await browser.close();
})();

